#include <iostream>

int main() {
    int amount = 0;
    if (std::cin >> amount) {
        // Demonstrating negation precedence
        bool wrongPrecedence = (!amount <= 50);
        bool correctPrecedence = !(amount <= 50);

        // Direct boolean assignment (Checkpoint 3.14 concept)
        bool isDivisibleByTen = (amount % 10 == 0);

        std::cout << "Input: " << amount << "\n";
        std::cout << "Wrong evaluation: " << wrongPrecedence << "\n";
        std::cout << "Correct evaluation: " << correctPrecedence << "\n";
        std::cout << "Divisible by 10: " << isDivisibleByTen << "\n";
    }
    return 0;
}

#include <iostream>

int main() {
    double weight = 0.0;
    double height = 0.0;
    if (std::cin >> weight >> height) {
        constexpr double KILOGRAMS_PER_POUND = 0.45359237;
        constexpr double METERS_PER_INCH = 0.0254;

        double weightInKilograms = weight * KILOGRAMS_PER_POUND;
        double heightInMeters = height * METERS_PER_INCH;
        double bmi = weightInKilograms / (heightInMeters * heightInMeters);

        std::cout << "BMI is " << bmi << "\n";
        if (bmi < 18.5) {
            std::cout << "Underweight\n";
        } else if (bmi < 25.0) {
            std::cout << "Normal\n";
        } else if (bmi < 30.0) {
            std::cout << "Overweight\n";
        } else {
            std::cout << "Obese\n";
        }
    }
    return 0;
}

#include <iostream>

int main() {
    int status = 0;
    double income = 0.0;
    if (std::cin >> status >> income) {
        double tax = 0.0;
        if (status == 0) { // Single filers (2009 brackets)
            if (income <= 8350) {
                tax = income * 0.10;
            } else if (income <= 33950) {
                tax = 8350 * 0.10 + (income - 8350) * 0.15;
            } else if (income <= 82250) {
                tax = 8350 * 0.10 + (33950 - 8350) * 0.15 + (income - 33950) * 0.25;
            } else {
                // Truncated for demo: standard progression
                tax = 8350 * 0.10 + (33950 - 8350) * 0.15 + (82250 - 33950) * 0.25 + (income - 82250) * 0.28;
            }
            std::cout << "Tax: " << tax << "\n";
        } else {
            std::cout << "Other status\n";
        }
    }
    return 0;
}
